SELECT id, title, detail, category, priority, due_date, completed, completed_at,
       created_at, updated_at
FROM todos


        AND title LIKE CONCAT('%', #{keyword}, '%')


        AND category = #{category}


        AND completed = FALSE


        AND due_date >= #{from}


        AND due_date <= #{to}


ORDER BY due_date IS NULL,


        due_date DESC, id DESC


        due_date ASC, id ASC


LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM todos

    AND title LIKE CONCAT('%', #{keyword}, '%')
    AND category = #{category}
    AND completed = FALSE
    AND due_date >= #{from}
    AND due_date <= #{to}
